@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
}

class Category {
  + Name : string
  + Price : double
}

class StayType {
  + Name : string
}

class Inhabitant {
  + Name : string
  + ID : string
}

class Registration {
  + RegistrationDate : date
  + BasicData : string
}

class Assessment {
  + NeedsSummary : string
  + RecommendedStayType : string
}

class WaitingList {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Status : string
}

class Invoice {
  + InvoiceNumber : int
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class PaymentEvent {
  + Amount : double
  + PaymentDate : date
}

class Stay {
  + StartDate : date
  + IsSuspended : boolean
  + DiscountRate : float
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
StayType "1" -- "1" Category

Inhabitant "1" -- "0..*" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" StayType
StayType "1" -- "0..*" WaitingList
WaitingList "1" -- "1" Inhabitant

Inhabitant "1" -- "1..*" Stay
Stay "1" -- "1" StayType
Stay "1" -- "0..*" Invoice

Invoice "1" -- "1..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote

@enduml

